function hotelOf(name){const q=normAr(name);if(!q)return null;return HOTELS.find(h=>{const n=normAr(h[0]);return q.includes(n)||n.includes(q.replace(/^فندق\s*/,""))})||null}
function homePos(){const H=profile.homes&&profile.homes[state.site];return (H&&H.confirmed&&typeof H.la==="number")?{name:H.home,la:H.la,lo:H.lo}:null}
function fmtD(m){m=Math.round(m);return m<1000?m+" م":(m/1000).toFixed(1)+" كم"}
function nearLand(la,lo,st){const L=LAND[st||state.site]||LAND.makkah;let best=null;for(const x of L){const d=kmBetween(la,lo,x[1],x[2])*1000;if(!best||d<best[1])best=[x[0],Math.round(d),x[1],x[2]]}return best}
/* وصف موقع حقيقي بالكلمات: داخل المطاف، أو قرب أقرب باب، أو المسافة والاتجاه من المسجد إن كان بعيدا */
function describePos(la,lo,st){st=st||state.site;const [ca,co]=CENTER[st];const km=kmBetween(la,lo,ca,co);const nm=SITES[st].name;const dir=dirOf(ca,co,la,lo);
  if(st==="makkah"&&km<0.09)return{text:"في المطاف",km,inside:true};
  if(km<1.5){const n=nearLand(la,lo,st);return{text:(km<0.25?"داخل "+nm+"، ":"")+"قرب "+n[0]+" ("+n[1]+" م)",km,inside:km<0.6,land:n}}
  return{text:"على بعد "+(km<10?km.toFixed(1):Math.round(km))+" كم "+dir+" "+nm+"، خارج نطاق المسجد",km,inside:false}}
function kmBetween(a,b,c,d){const R=6371,dl=(c-a)*Math.PI/180,dn=(d-b)*Math.PI/180;const x=Math.sin(dl/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
