const MASAR={path:[[21.4165,39.7896],[21.4245,39.7920],[21.4235,39.8080],[21.4240,39.8135],[21.4222,39.8213]],halfKm:0.45,endKm:0.5};
function masarPos(la,lo){const P=MASAR.path;const kx=111.32*Math.cos(la*Math.PI/180),ky=110.57;let best=null;let acc=[];let tot=0;for(let i=P.length-1;i>0;i--){const d=Math.hypot((P[i][0]-P[i-1][0])*ky,(P[i][1]-P[i-1][1])*kx);acc[i-1]=tot;tot+=d}
  for(let i=0;i<P.length-1;i++){const ax=(P[i][1])*kx,ay=P[i][0]*ky,bx=P[i+1][1]*kx,by=P[i+1][0]*ky,px=lo*kx,py=la*ky;const vx=bx-ax,vy=by-ay;const L2=vx*vx+vy*vy;let t=L2?((px-ax)*vx+(py-ay)*vy)/L2:0;t=Math.max(0,Math.min(1,t));const qx=ax+t*vx,qy=ay+t*vy;const d=Math.hypot(px-qx,py-qy);const segLen=Math.sqrt(L2);const rem=acc[i]+(1-t)*segLen;if(best===null||d<best.d)best={d,rem}}
  return{in:best.d<=MASAR.halfKm,d:+best.d.toFixed(2),walkKm:+(best.rem+MASAR.endKm).toFixed(1)}}
function realSense(){
  if(!navigator.geolocation||state.realTried||state.simLoc)return;state.realTried=true;
  navigator.geolocation.getCurrentPosition(async pos=>{
    const {latitude:la,longitude:lo}=pos.coords;if(mashaerAt(la,lo)&&state.site!=="makkah"){log("sup","موقع الهاتف الحقيقي في المشاعر المقدسة","تبديل الموقع إلى مكة");state.realTried=false;setSite("makkah");return}const near=Object.keys(CENTER).map(k=>[k,kmBetween(la,lo,...CENTER[k])]).sort((a,b)=>a[1]-b[1])[0];if(near[1]<3&&near[0]!==state.site){log("sup","موقع الهاتف الحقيقي داخل "+SITES[near[0]].name,"تبديل الموقع تلقائيا");state.realTried=false;setSite(near[0]);return}
    const [ca,co]=CENTER[state.site];const km=kmBetween(la,lo,ca,co);state.real={la,lo,km};refreshCartPlaces();try{mashaerSense(la,lo)}catch(_){}
    if(state.site==="makkah"&&km<0.15&&!state.mutawwifOffered){state.mutawwifOffered=true;log("rite","الموقع الحقيقي داخل المطاف: يعرض المطوف الرقمي تلقائيا",Math.round(km*1000)+" م من الكعبة");
      card(head("🕋","أنت في المطاف","من موقع جوالك")+`<div>أفتح لك المطوف الرقمي: عداد الأشواط والأدعية بلغتك، وأذكرك بالماء في منتصف الطواف.</div><div class="acts"><button class="primary" data-say="افتح المطوف">افتح المطوف</button><button data-say="كثافة المطاف الآن؟">كثافة المطاف</button></div>`,"nav")}
    const dir=(()=>{const dLon=(lo-co)*Math.PI/180,p1=ca*Math.PI/180,p2=la*Math.PI/180;const y=Math.sin(dLon)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dLon);const b=(Math.atan2(y,x)*180/Math.PI+360)%360;return ["شمال","شمال شرق","شرق","جنوب شرق","جنوب","جنوب غرب","غرب","شمال غرب"][Math.round(b/45)%8]})();
    const where=km<0.6?"داخل "+site().name+" أو ساحاته":km<1.5?"على بعد "+Math.round(km*1000)+" م "+dir+" "+site().name:"على بعد "+(km<10?km.toFixed(1):Math.round(km))+" كم "+dir+" "+site().name;
    const entry=state.site==="makkah"?"باب الملك عبدالعزيز (1)":(profile.gender==="f"?"مداخل النساء في الجهة الشمالية":"باب السلام (1)، وللروضة بالتصريح ساحات باب مكة (37)");
    state.realWhere=where+" · مدخلك: "+entry;
    const dirEN=["north","north-east","east","south-east","south","south-west","west","north-west"][["شمال","شمال شرق","شرق","جنوب شرق","جنوب","جنوب غرب","غرب","شمال غرب"].indexOf(dir)];const nmEN=SITE_EN[state.site].name;
    state.realWhereEN=(km<0.6?"inside "+nmEN+" or its courtyards":km<1.5?Math.round(km*1000)+" m "+dirEN+" of "+nmEN:(km<10?km.toFixed(1):Math.round(km))+" km "+dirEN+" of "+nmEN)+" · your entrance: "+(state.site==="makkah"?"King Abdulaziz Gate (1)":(profile.gender==="f"?"the women's entrances on the north side":"Bab As-Salam (1); for the Rawdah with a permit, Bab Makkah courtyards (37)"));
    if(km<1.5){log("sup","موقع الهاتف الحقيقي: "+where,km.toFixed(2)+" كم من المركز")}
    else{log("sup","موقع الهاتف الحقيقي: "+where,"الطقس من موقعك الفعلي")}
    setTimeout(()=>{$("#locText").innerHTML=T("موقعك الآن: ","Your location: ")+"<b>"+esc(isEN()?state.realWhereEN:state.realWhere)+"</b> <span style=\"color:var(--muted)\">(GPS)</span>"+(state.groupCode?T(" · مجموعة "," · group ")+"<b>"+esc(state.groupCode)+"</b>":"")},950);
    try{const r=await fetch("https://api.open-meteo.com/v1/forecast?latitude="+la.toFixed(3)+"&longitude="+lo.toFixed(3)+"&current=temperature_2m,relative_humidity_2m&timezone=auto");const j=await r.json();
      const t=Math.round(j.current.temperature_2m),h=j.current.relative_humidity_2m;SITES[state.site].temp=t;$(".sb span:last-child").textContent=cityName()+" · "+t+"°";wbRender();
      log("care","طقس حقيقي من موقع الهاتف",t+"° · رطوبة "+h+"% (Open-Meteo)")}catch(_){log("care","الطقس الحي غير متاح في هذا العارض","أبقي قيمة المحاكاة")}
  },err=>{log("sup","تحديد الموقع الحقيقي غير متاح هنا ("+(err&&err.message||"")+")","أبقي موقع المحاكاة");setTimeout(()=>{const s=site();$("#locText").innerHTML=T("موقعك الآن: ","Your location: ")+"<b>"+esc(siteName())+"</b>"+(isEN()?' <span style="color:var(--muted)">(simulated: the phone has not allowed location; enable it in browser settings)</span>':" · "+esc(s.spot)+' <span style="color:var(--muted)">(محاكاة: الجوال لم يأذن بالموقع، اسمح به من إعدادات المتصفح)</span>')},950)},{timeout:8000,maximumAge:60000});}
/* أول فتح على الجهاز: طلب إذن الموقع بلمسة من الضيف (الجوال لا يعرض نافذة الإذن إلا بعد لمسة)، ثم يختفي بعد الموافقة */
