/* رقم الجوال: نقبل الأرقام العربية واللاتينية، ونطبع الرقم السعودي إلى الصيغة الدولية، ونرفض الأرقام الناقصة */
function normPhone(t){let d=String(t||"").replace(/[٠-٩]/g,c=>"٠١٢٣٤٥٦٧٨٩".indexOf(c)).replace(/[^\d+]/g,"");if(d.startsWith("00"))d="+"+d.slice(2);
  if(/^05\d{8}$/.test(d))return "+966"+d.slice(1);if(/^5\d{8}$/.test(d))return "+966"+d;if(/^\+9665\d{8}$/.test(d))return d;if(/^9665\d{8}$/.test(d))return "+"+d;
  if(/^\+\d{8,15}$/.test(d)&&!d.startsWith("+966"))return d;return null}
