  const direct=await new Promise(res=>{let done=false;const fin=v=>{if(!done){done=true;res(v)}};try{navigator.geolocation.getCurrentPosition(()=>fin(true),()=>fin(false),{timeout:8000,maximumAge:60000})}catch(_){fin(false)}setTimeout(()=>fin(false),9000)});
